import 'package:flutter/material.dart';
import 'core.dart';
import 'branded_store.dart';
import 'category_hub.dart';

class ShowcaseHomePage extends StatefulWidget {
  final String customerName;
  final String phone;
  const ShowcaseHomePage({super.key, required this.customerName, required this.phone});
  @override State<ShowcaseHomePage> createState()=>_ShowcaseHomePageState();
}
class _ShowcaseHomePageState extends State<ShowcaseHomePage>{
 final repo=Repo(); late Future<List<Store>> storesFuture; int tab=0;
 @override void initState(){super.initState();storesFuture=repo.stores();}
 Future<void> openStore(Store s)async{if(!s.isOpen)return;await Navigator.push(context,MaterialPageRoute(builder:(_)=>BrandedStorePage(store:s,customerName:widget.customerName,phone:widget.phone,repo:repo)));}
