 @override Widget build(BuildContext context)=>Scaffold(backgroundColor:appBg,bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const [NavigationDestination(icon:Icon(Icons.home_rounded),label:'Início'),NavigationDestination(icon:Icon(Icons.search_rounded),label:'Buscar'),NavigationDestination(icon:Icon(Icons.receipt_long_rounded),label:'Pedidos'),NavigationDestination(icon:Icon(Icons.explore_outlined),label:'Explorar'),NavigationDestination(icon:Icon(Icons.person_outline_rounded),label:'Conta')]),body:SafeArea(child:FutureBuilder<List<Store>>(future:storesFuture,builder:(_,snap){final stores=snap.data??<Store>[];if(tab!=0)return _simpleTab(tab);return RefreshIndicator(onRefresh:()async=>setState(()=>storesFuture=repo.stores()),child:ListView(padding:const EdgeInsets.fromLTRB(17,12,17,28),children:[_header(),const SizedBox(height:18),Container(height:58,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(19)),child:const Row(children:[SizedBox(width:18),Icon(Icons.search_rounded,size:28),SizedBox(width:14),Expanded(child:Text('O que você procura no Vale?',style:TextStyle(color:brandMuted,fontSize:16)))])),const SizedBox(height:22),const Text('Tudo por aqui',style:TextStyle(fontSize:21,fontWeight:FontWeight.w900)),const SizedBox(height:12),_categories(),const SizedBox(height:22),const Text('Parceiros em destaque',style:TextStyle(fontSize:21,fontWeight:FontWeight.w900)),const SizedBox(height:11),_partners(stores),const SizedBox(height:26),const Text('Mais do que delivery',style:TextStyle(fontSize:21,fontWeight:FontWeight.w900)),const SizedBox(height:12),Row(children:[Expanded(child:_explore('Hospedagens',Icons.hotel_rounded,()=>openCategory('Hospedagem'))),const SizedBox(width:10),Expanded(child:_explore('Experiências',Icons.hiking_rounded,()=>openCategory('Experiências'))),const SizedBox(width:10),Expanded(child:_explore('Eventos',Icons.local_activity_rounded,()=>openCategory('Eventos')))])]));})));
