 Widget _categories(){const items=[('Comida',Icons.lunch_dining_rounded),('Café',Icons.coffee_rounded),('Pizza',Icons.local_pizza_rounded),('Mercado',Icons.shopping_basket_rounded),('Hospedagem',Icons.hotel_rounded),('Experiências',Icons.hiking_rounded),('Eventos',Icons.local_activity_rounded)];return SizedBox(height:108,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:items.length,separatorBuilder:(_,__)=>const SizedBox(width:10),itemBuilder:(_,i){final x=items[i];return InkWell(onTap:()=>openCategory(x.$1),child:SizedBox(width:74,child:Column(children:[Container(width:68,height:68,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20)),child:Icon(x.$2,color:brandRed,size:32)),const SizedBox(height:7),Text(x.$1,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:10,fontWeight:FontWeight.w800))]))); }));}
 Widget _partners(List<Store> stores){if(stores.isEmpty)return const SizedBox(height:110,child:Center(child:Text('Parceiros em atualização',style:TextStyle(color:brandMuted))));return SizedBox(height:142,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:stores.length,separatorBuilder:(_,__)=>const SizedBox(width:10),itemBuilder:(_,i){final s=stores[i];return InkWell(onTap:()=>openStore(s),child:Container(width:128,padding:const EdgeInsets.all(10),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(22)),child:Column(children:[ClipRRect(borderRadius:BorderRadius.circular(16),child:SizedBox(width:76,height:76,child:s.logoUrl.isNotEmpty?Image.network(s.logoUrl,fit:BoxFit.cover,errorBuilder:(_,__,___)=>Image.asset(s.localLogo,fit:BoxFit.cover)):Image.asset(s.localLogo,fit:BoxFit.cover))),const SizedBox(height:8),Text(s.name,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:11,fontWeight:FontWeight.w900))]))); }));}
